diff --git a/tests/sites.test.js b/tests/sites.test.js
new file mode 100644
index 0000000..d00693a
--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,96 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, NOW } from "./helpers.js";
+import { receiveOrder } from "../src/domain/orders.js";
+
+const ANNEX = { "X-Larder-Site": "annex" };
+
+// Puts 3 l of milk (item 2) into the annex fridge via order 2 (sent: milk 12, butter 2).
+function stockAnnex(store) {
+  receiveOrder(store, 2, [
+    { lot: "AX-1", expires: "2026-10-30", location: "annex-fridge" },
+    { lot: "AX-2", expires: null, location: "annex-fridge" },
+  ], { at: new Date(NOW).toISOString() });
+}
+
+test("the seed has two sites and every location has one", () => {
+  const { store } = app();
+  assert.deepEqual(store.data.sites.map((s) => s.id), ["main", "annex"]);
+  assert.ok(store.data.locations.every((l) => l.site));
+  assert.deepEqual(store.data.locations.find((l) => l.id === "annex-fridge"), { id: "annex-fridge", name: "Annex fridge", tempC: 4, site: "annex" });
+});
+
+test("an unknown site is a 400 unknown_site", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "nowhere" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /nowhere/);
+});
+
+test("without the header the site is main", async () => {
+  const { store, handle } = app();
+  stockAnnex(store);
+  const batches = (await handle({ path: "/batches" })).body;
+  assert.ok(batches.length > 0);
+  assert.ok(batches.every((b) => b.location !== "annex-fridge"));
+});
+
+test("batches and stock on hand only see the request's site; items are shared", async () => {
+  const { store, handle } = app();
+  stockAnnex(store);
+  const annexItems = (await handle({ path: "/items", headers: ANNEX })).body;
+  assert.equal(annexItems.length, store.data.items.length);
+  assert.equal(annexItems.find((i) => i.id === 2).onHand, 12);
+  assert.equal(annexItems.find((i) => i.id === 1).onHand, 0);
+  const mainMilk = (await handle({ path: "/items/2" })).body;
+  assert.equal(mainMilk.onHand, 10);
+  assert.ok(mainMilk.batches.every((b) => b.location === "fridge"));
+  const annexBatches = (await handle({ path: "/batches", headers: ANNEX })).body;
+  assert.deepEqual(annexBatches.map((b) => b.lot), ["AX-1", "AX-2"]);
+  assert.equal((await handle({ path: "/batches/1", headers: ANNEX })).body.error.code, "unknown_batch");
+  const waste = await handle({ method: "POST", path: "/batches/1/waste", headers: ANNEX, body: { qty: 1 } });
+  assert.equal(waste.status, 404);
+  assert.equal(store.data.batches.find((b) => b.id === 1).qty, 4);
+});
+
+test("cooking uses only the request's site stock", async () => {
+  const { store, handle } = app();
+  stockAnnex(store);
+  // bechamel needs milk, butter and flour; the annex has no flour.
+  const res = await handle({ method: "POST", path: "/recipes/2/cook", headers: ANNEX, body: { portions: 10 } });
+  assert.equal(res.status, 409);
+  assert.equal(res.body.error.code, "not_enough_stock");
+  assert.equal(store.data.batches.find((b) => b.lot === "AX-1").qty, 12);
+  const before = store.data.batches.find((b) => b.lot === "AX-1").qty;
+  const ok = await handle({ method: "POST", path: "/recipes/2/cook", body: { portions: 10 } });
+  assert.equal(ok.status, 200);
+  assert.equal(store.data.batches.find((b) => b.lot === "AX-1").qty, before);
+});
+
+test("alerts and stock value only see the request's site", async () => {
+  const { store, handle } = app();
+  stockAnnex(store);
+  const alerts = (await handle({ path: "/alerts", headers: ANNEX })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.lot), ["AX-1"]);
+  assert.ok(alerts.lowStock.some((i) => i.name === "onion"));
+  assert.ok(!alerts.lowStock.some((i) => i.name === "milk"));
+  const value = (await handle({ path: "/reports/stock-value", headers: ANNEX })).body;
+  assert.equal(value.totalCents, 12 * 129 + 2 * 945);
+  const mainValue = (await handle({ path: "/reports/stock-value" })).body;
+  assert.equal(mainValue.lines.find((l) => l.itemId === 2).qty, 10);
+});
+
+test("stock-takes only see the request's site", async () => {
+  const { store, handle } = app();
+  stockAnnex(store);
+  const wrong = await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "fridge" } });
+  assert.equal(wrong.body.error.code, "unknown_location");
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: ANNEX, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 404);
+  const ax1 = store.data.batches.find((b) => b.lot === "AX-1");
+  await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: ANNEX, body: { batchId: ax1.id, counted: 11 } });
+  const res = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: ANNEX });
+  assert.equal(res.status, 200);
+  assert.equal(ax1.qty, 11);
+});
